// ============================================================
// Score & Rank — the product owner's Phase 1 scoring, applied to real conversations.
// ============================================================
// Rules rather than an LLM ON PURPOSE: when the product owner asks "why is this person
// ranked third?", every point is traceable to one of the signals from his
// own document, and he can tune the weights. An AI-written summary can be
// layered on later -- but it must use a SEPARATE session id, because
// calling /ai/chat with the customer's own wa_<phone> would write our
// analysis into their live conversation memory.
// ============================================================

// Staff, test and company numbers. EXTEND THIS LIST rather than filtering
// by hand in the sheet.
const INTERNAL = ['10000000001', '10000000000', '10000000002'];

const DAILY_LIMIT = 10; // the team's stated call capacity

// FIXED 2026-08-18 (found on the first real run): a session with 1018 turns
// in 79 minutes ranked 4th, and its "user" messages were OUR OWN bot menu
// text -- something replays our output back through /ai/chat under
// role=user, so the scorer was matching our own keywords and awarding
// points for them. Two independent guards, because either alone could be
// fooled: a human does not send a thousand messages in an hour, and a real
// customer does not quote our menu back at us.
const MAX_HUMAN_TURNS = 100;
const BOT_FINGERPRINT = /(How can we help today|Track my shipment|Get a shipping quote|Become an ACME Partner|Welcome to ACME|Thanks! To get you a quote)/i;

const transcripts = $('Fetch Transcripts').all().map(i => i.json).filter(r => r && r.session_id);
const contexts = $('Fetch Lead Context').all().map(i => i.json).filter(r => r && r.phone);
const existing = $('Read Existing List').all().map(i => i.json).filter(r => r && r.phone);

// Anyone the team has already picked up drops off the list permanently.
const contacted = new Set(
  existing.filter(r => String(r.call_status || '').trim() !== '').map(r => String(r.phone).trim())
);

const tByPhone = {};
for (const t of transcripts) {
  const phone = String(t.session_id).slice(3);
  tByPhone[phone] = t;
}
const cByPhone = {};
for (const c of contexts) cByPhone[String(c.phone)] = c;

const allPhones = new Set([...Object.keys(tByPhone), ...Object.keys(cByPhone)]);

const SIGNALS = [
  { key: 'price_or_transit', points: 2, label: 'asked about price or transit time',
    re: /\b(price|prices|pricing|cost|costs|rate|rates|charge|how much|quotation|transit|how long|how many days|duration|lead time)\b/i },
  { key: 'services', points: 2, label: 'asked about customs / warehousing / delivery / COD',
    re: /\b(customs|clearance|duty|duties|tax|warehouse|storage|door to door|door-to-door|last mile|delivery fee|cod|cash on delivery)\b/i },
  { key: 'address', points: 2, label: 'asked for our office or warehouse address',
    re: /\b(address|office|located|location|where are you|pick ?up point|drop ?off)\b/i },
  { key: 'shipping_soon', points: 2, label: 'says they are shipping soon',
    re: /\b(soon|urgent|urgently|asap|immediately|right away|next week|this week|this month|ready to ship|want to ship now)\b/i },
  { key: 'how_to_ship', points: 1, label: 'asked how to ship from overseas',
    re: /\b(how (do|can|would) i ship|how to ship|start shipping|ship from china|import from china)\b/i },
  { key: 'cargo_text', points: 1, label: 'described cargo in conversation',
    re: /\b(\d+\s?(kg|kgs|cbm|tons?|pieces|pcs|cartons?|boxes)|electronics|phone parts|batteries|clothes|furniture|machinery|spare parts)\b/i }
];

const out = [];

for (const phone of allPhones) {
  if (INTERNAL.includes(phone)) continue;                 // staff / test numbers
  if (phone.length < 8 || phone.length > 15) continue;    // junk from the old group-JID bug
  if (contacted.has(phone)) continue;                     // already phoned

  const t = tByPhone[phone] || {};
  const c = cByPhone[phone] || {};

  // the product owner, 2026-08-14: Phase 1 is shipping customers only.
  const state = String(c.current_state || '');
  if (state.indexOf('PARTNER') === 0) continue;

  const orderCount = Number(c.order_count || 0);
  if (orderCount > 0) continue;   // already an active shipper, not a lead

  let ctx = c.current_context;
  if (typeof ctx === 'string') { try { ctx = JSON.parse(ctx); } catch (e) { ctx = {}; } }
  const f = (ctx && ctx.fields) || {};

  const text = String(t.user_text || '');
  const turns = Number(t.turns || 0);

  let score = 0;
  const why = [];
  function award(points, label) { score += points; why.push(label); }

  // Strongest signal: they have actual goods with numbers attached.
  const hasCargoFields = ['weight_kg', 'volume_cbm', 'cargo_category', 'destination_country']
    .some(k => f[k] !== undefined && f[k] !== null && f[k] !== '');
  if (hasCargoFields) award(3, 'gave cargo details');

  if (state.indexOf('QUOTE') === 0) award(3, 'started a quote');
  if (state === 'QUOTE_CONFIRMING') award(2, 'reached the confirmation step but never submitted');

  for (const s of SIGNALS) {
    if (s.re.test(text)) award(s.points, s.label);
  }

  if (c.conversion_source) award(1, 'came from a paid ad');
  if (turns >= 6) award(1, 'engaged conversation (' + turns + ' turns)');

  // Not a genuine human conversation -- see MAX_HUMAN_TURNS note above.
  if (turns > MAX_HUMAN_TURNS) continue;
  if (BOT_FINGERPRINT.test(text)) continue;

  if (score <= 0) continue;

  // Recalibrated 2026-08-18 against the first real run: the original 7/4
  // cut-offs made 8 of 10 leads "HOT", which is no triage at all. Real
  // scores ran 12,11,11,9,8,8,8,7,6,6 -- these thresholds put the genuinely
  // exceptional ones at the top and leave the rest as solid follow-ups.
  const tier = score >= 10 ? 'HOT' : (score >= 6 ? 'WARM' : 'COLD');

  const bits = [];
  if (f.destination_country) bits.push('to ' + f.destination_country);
  if (f.weight_kg) bits.push(f.weight_kg + 'kg');
  if (f.volume_cbm) bits.push(f.volume_cbm + ' CBM');
  if (f.cargo_category) bits.push(String(f.cargo_category));
  if (f.shipping_method) bits.push(String(f.shipping_method) + ' freight');
  const firstMsg = String(t.first_user_message || '').replace(/\s+/g, ' ').slice(0, 160);
  const summary = (bits.length ? bits.join(', ') + '. ' : '') + (firstMsg ? 'First said: "' + firstMsg + '"' : '');

  out.push({
    phone: phone,
    name: f.customer_name || f.contact_name || '',
    score: score,
    tier: tier,
    status: c.is_registered === true ? 'Registered - never ordered' : 'Not registered',
    summary: summary,
    why: why.join('; '),
    destination_country: f.destination_country || '',
    weight_kg: f.weight_kg === undefined || f.weight_kg === null ? '' : f.weight_kg,
    volume_cbm: f.volume_cbm === undefined || f.volume_cbm === null ? '' : f.volume_cbm,
    cargo_category: f.cargo_category || '',
    shipping_method: f.shipping_method || '',
    ad_source: c.source_app || c.conversion_source || '',
    ad_name: c.ad_title || '',
    ad_id: c.source_id || '',
    turns: turns,
    first_seen: c.first_seen || t.first_at || '',
    last_activity: c.last_activity || t.last_at || '',
    listed_date: new Date().toISOString().slice(0, 10)
  });
}

// Highest score first; break ties on who spoke to us most recently.
out.sort((a, b) => (b.score - a.score) || (String(b.last_activity).localeCompare(String(a.last_activity))));

return out.slice(0, DAILY_LIMIT).map((r, i) => ({ json: Object.assign({ rank: i + 1 }, r) }));
